import{_ as t,o as n,c as o,a3 as a}from"./chunks/framework.BTQ4eCVb.js";const m=JSON.parse('{"title":"Announcements — Developer Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Announcements — Developer Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/announcements"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Announcements — Developer Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/announcements"}]]},"headers":[],"relativePath":"developer-guide/announcements.md","filePath":"developer-guide/announcements.md","lastUpdated":1788123957000}'),d={name:"developer-guide/announcements.md"};function c(i,e,s,r,l,u){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="announcements-—-developer-guide" tabindex="-1">Announcements — Developer Guide <a class="header-anchor" href="#announcements-—-developer-guide" aria-label="Permalink to &quot;Announcements — Developer Guide&quot;">​</a></h1><p>Marketplace Communication module. Flat namespaces (no <code>Modules/</code> package). <strong>Authz exception:</strong> consumer read paths intentionally omit <code>announcements.view</code>.</p><h2 id="backend-layout" tabindex="-1">Backend layout <a class="header-anchor" href="#backend-layout" aria-label="Permalink to &quot;Backend layout&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Path</th></tr></thead><tbody><tr><td>Models</td><td><code>app/Models/Announcement.php</code>, <code>AnnouncementRead.php</code></td></tr><tr><td>Enum</td><td><code>app/Enums/Tenant/AnnouncementStatusEnum</code></td></tr><tr><td>Service</td><td><code>app/Services/Tenant/AnnouncementService.php</code></td></tr><tr><td>Controller</td><td><code>app/Http/Controllers/Tenant/Api/V1/AnnouncementController.php</code></td></tr><tr><td>Requests</td><td><code>app/Http/Requests/Tenant/Api/V1/Announcement/*</code></td></tr><tr><td>Resources</td><td><code>app/Http/Resources/Tenant/Api/V1/Announcement/*</code></td></tr><tr><td>Policy</td><td><code>app/Policies/AnnouncementPolicy.php</code></td></tr><tr><td>Events</td><td><code>AnnouncementCreated</code>, <code>Updated</code>, <code>Deleted</code>, <code>Published</code></td></tr><tr><td>Subscriber</td><td><code>app/Listeners/AnnouncementEventSubscriber.php</code></td></tr><tr><td>Publish fan-out job</td><td><code>app/Jobs/Tenant/NotifyAnnouncementPublishedJob.php</code> (chunks users; skips suspended)</td></tr><tr><td>Notification</td><td><code>app/Notifications/Tenant/Announcement/AnnouncementPublishedNotification.php</code> (<code>type: announcement</code>)</td></tr><tr><td>Tests</td><td><code>tests/Feature/Tenant/Announcement/AnnouncementTest.php</code></td></tr></tbody></table><h2 id="authz" tabindex="-1">Authz <a class="header-anchor" href="#authz" aria-label="Permalink to &quot;Authz&quot;">​</a></h2><ul><li>Routes: <code>module:announcements</code> for all endpoints</li><li>Consumer (<code>unread</code>, <code>inbox</code>, <code>index</code> published, <code>show</code> published, <code>read</code>): <strong>no</strong> <code>can:</code> middleware; <code>AnnouncementPolicy::viewAny</code> / <code>view</code> allow any authenticated user for published non-expired rows</li><li>Mutations: <code>can:announcements.create|update|delete|restore|force.delete</code></li><li>Readers: <code>can:announcements.view_reads</code></li></ul><p>Do <strong>not</strong> add <code>announcements.view</code> without a product decision — reading is intentionally open once installed.</p><h2 id="read-receipts" tabindex="-1">Read receipts <a class="header-anchor" href="#read-receipts" aria-label="Permalink to &quot;Read receipts&quot;">​</a></h2><p><code>announcement_reads</code>: unique <code>(announcement_id, user_id)</code>, <code>first_read_at</code> / <code>last_read_at</code>, <code>first_read_ip</code> / <code>last_read_ip</code>. First mark-read sets first_* ; later marks bump last_* only. <code>markRead</code> uses <code>firstOrCreate</code> with unique-constraint retry so concurrent double-submit is safe.</p><h2 id="date-and-time" tabindex="-1">Date and time <a class="header-anchor" href="#date-and-time" aria-label="Permalink to &quot;Date and time&quot;">​</a></h2><p>Absolute columns use <code>UtcDateTime</code>. Audience visibility SQL compares <code>expires_at</code> to <code>UtcInstant::now()</code> / <code>now(&#39;UTC&#39;)</code> (never workspace <code>app.timezone</code>). SPA <code>expires_at</code> edit/display uses <code>isoToAppLocalInput</code> / <code>appLocalInputToIso</code>.</p><h2 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h2><p><code>DashboardWidgetService</code> emits <code>announcements_inbox</code> when <code>EntitlementService::hasModule(..., &#39;announcements&#39;)</code> (permission field may be null). SPA dashboard card fetches <strong>unread</strong> only and renders only when that list is non-empty (hidden after the user has read everything).</p><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h2><ul><li>Pages: <code>src/pages/announcements/</code> (<code>announcements-page.tsx</code>, <code>announcement-form.tsx</code>, <code>announcement-form-page.tsx</code>, <code>announcement-view-page.tsx</code>)</li><li>Post-login dialog: <code>src/components/announcements/announcement-inbox-dialog.tsx</code> in <code>AppLayout</code></li><li>Dashboard section: <code>src/components/dashboard/announcements-dashboard-section.tsx</code></li><li>Notifications: <code>src/notifications/modules/system.ts</code> deep-links to <code>/announcements/:id</code></li><li>Nav: module-only (no permission field)</li><li>Playwright: <code>npm run test:e2e:announcements</code></li></ul><h2 id="permissions-config" tabindex="-1">Permissions config <a class="header-anchor" href="#permissions-config" aria-label="Permalink to &quot;Permissions config&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>announcements.create | update | delete | restore | force.delete | view_reads</span></span></code></pre></div><h2 id="catalog-registration" tabindex="-1">Catalog registration <a class="header-anchor" href="#catalog-registration" aria-label="Permalink to &quot;Catalog registration&quot;">​</a></h2><p>Data migration <code>register_announcements_module</code> (<code>is_default_included: false</code>, <code>is_billable: false</code>) — <strong>no</strong> <code>installForWorkspacesMissingModule</code>. Permissions sync migration grants defaults additively.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/api/tenant-v1-announcements">API</a></li><li><a href="/deployment/announcements">Deployment</a></li><li><a href="/user-guide/announcements">User guide</a></li><li><a href="/developer-guide/module-development">Module development</a></li></ul>',21)])])}const h=t(d,[["render",c]]);export{m as __pageData,h as default};
